      faq: {
        id: 'faq',
        title: 'Perguntas Frequentes',
        faqs: [
          { q: 'Posso rodar o DeepSeek-R1 completo de 671B localmente?', a: 'Não. O DeepSeek-R1 completo é um modelo Mixture-of-Experts de 671B parâmetros (~37B ativos por token) e precisa de aproximadamente 376–404 GB de VRAM em Q4 — apenas hardware de datacenter. Em casa você roda um de seus destilados (1.5B a 70B). Existe uma build Unsloth de 1.58-bit (~131 GB), mas ela roda a cerca de 0.3 tokens/segundo, o que é uma curiosidade em vez de uma configuração utilizável.' },
          { q: 'Qual destilado do DeepSeek-R1 é o melhor geral?', a: 'Para a maioria das pessoas, o DeepSeek-R1-Distill-Qwen-14B em uma GPU de 16 GB é o melhor equilíbrio entre qualidade de raciocínio, velocidade e ajuste de VRAM. Se você tem uma placa de 24 GB, o destilado 32B é mais forte e supera o OpenAI o1-mini em vários benchmarks de raciocínio.' },
          { q: 'Qual é o melhor modelo de raciocínio pequeno da DeepSeek?', a: 'O DeepSeek-R1-0528-Qwen3-8B. Ele é destilado do R1-0528 atualizado sobre uma base Qwen3 8B, lidera os modelos abertos de 8B no AIME 2024 e pontua cerca de 10 pontos acima do Qwen3 8B base. Ele serve uma GPU de 8 GB em Q4_K_M.' },
          { q: 'Quanta VRAM cada destilado precisa?', a: 'No padrão Q4_K_M do Ollama: o 7B precisa de ~8 GB (arquivo ~4.7 GB), o 14B precisa de ~16 GB (arquivo ~9 GB), o 32B precisa de ~24 GB (arquivo ~18–20 GB) e o 70B precisa de dual-GPU ou 48 GB (arquivo ~40 GB). FP16 é aproximadamente 4× o tamanho do Q4_K_M; Q8_0 é aproximadamente 2×.' },
          { q: 'O DeepSeek-R1 é bom em programação?', a: 'Este guia classifica apenas raciocínio (matemática, lógica, múltiplas etapas). Para geração de código, os trade-offs são diferentes — veja nossa comparação dedicada em /power-local-llm/deepseek-vs-qwen-coding-local-2026 em vez de escolher um destilado de raciocínio para produtividade de programação.' },
          { q: 'Qual é a diferença entre o DeepSeek-V3 e o DeepSeek-R1?', a: 'O DeepSeek-V3 é um modelo de chat ajustado para conversa; o DeepSeek-R1 é um modelo de raciocínio que produz uma cadeia de pensamento explícita antes de responder. Para matemática e lógica, use o R1 ou um destilado; para chat geral, use o V3.' },
          { q: 'Por que o meu destilado do DeepSeek-R1 entra em loop ou produz besteira?', a: 'Quase sempre um problema de configuração. Defina a temperatura em 0.6 (0.5–0.7 está bom) e remova qualquer system prompt — coloque todas as instruções na mensagem do usuário. Os destilados R1 têm um modo de falha de repetição conhecido, disparado por system prompts e temperaturas extremas.' },
          { q: 'Como eu instalo um destilado do DeepSeek-R1?', a: 'Instale o Ollama, depois rode um comando para o seu nível, por exemplo `ollama run deepseek-r1:14b`. Todos os destilados têm Q4_K_M como padrão. Veja a seção de configuração acima para a lista completa de comandos.' },
          { q: 'O destilado 8B tem uma licença diferente?', a: 'Sim. O DeepSeek-R1-Distill-Llama-8B carrega a licença Llama 3 além da MIT, porque sua base é o Llama 3. Os destilados baseados em Qwen (1.5B, 7B, 14B, 32B) herdam o licenciamento Qwen. Verifique a licença antes do uso comercial.' },
          { q: 'Devo comprar uma RTX 4060 Ti 16GB ou uma RTX 4090 para raciocínio?', a: 'Se o seu orçamento permite a RTX 4090 e você quer rodar o destilado 32B (que supera o o1-mini), compre a 4090. Se você quer o melhor custo-benefício e o destilado 14B atende às suas necessidades, a RTX 4060 Ti 16GB a ~$420 é a compra mais inteligente.' },
        ],
      },
